require_once __DIR__.'/auth_check.php';require_role(['Doctor','Hospital Admin','System Admin']);ensure_clinical_tables();if($_SERVER['REQUEST_METHOD']!=='POST'||!csrf_check($_POST['_csrf']??null)){$_SESSION['errors']=['Invalid verification request.'];redirect('../medical_documents.php');}$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'');if(!in_array($status,['Verified','Rejected'],true)){$_SESSION['errors']=['Invalid verification status.'];redirect('../medical_documents.php');}$s=db()->prepare('SELECT patient_id FROM medical_documents WHERE id=?');$s->execute([$id]);$doc=$s->fetch();if(!$doc||($_SESSION['role']==='Doctor'&&!active_access((int)$doc['patient_id'],(int)$_SESSION['user_id']))){$_SESSION['errors']=['Document access denied.'];redirect('../patient_search.php');}$u=db()->prepare('UPDATE medical_documents SET verification_status=?,verified_by=?,verified_at=NOW() WHERE id=?');$u->execute([$status,(int)$_SESSION['user_id'],$id]);create_notification((int)$doc['patient_id'],'Document '.$status,'A medical document was marked '.$status.'.','medical_document');$_SESSION['success']='Document status updated.';redirect('../medical_documents.php?patient='.(int)$doc['patient_id']);
